 using Microsoft.EntityFrameworkCore;
 using Microsoft.EntityFrameworkCore.ChangeTracking;
 using Microsoft.EntityFrameworkCore.ValueGeneration;

 class ProductContext : DbContext
 {
     public DbSet<Product> Products => Set<Product>();

     protected override void OnModelCreating(ModelBuilder modelBuilder)
     {
         modelBuilder.Entity<Product>(entity =>
         {
             entity.ToContainer("Products");
             entity.HasIndex(p => p.Sku);

             // BREAKING CHANGE 1: Discriminator property renamed "$type" in EF Core 9.
             // Our 500K existing documents use "Discriminator" and our raw SQL queries
             // reference c.Discriminator. Explicitly set the old name to preserve compat.
             entity.HasDiscriminator<string>("Discriminator")
                   .HasValue<Product>("Product");

             // BREAKING CHANGE 2: The JSON "id" property format changed.
             // EF Core 8 stored: "Product|123"  (i.e. "EntityType|KeyValue")
             // EF Core 9 stores: "123"          (just the key value)
             // Existing documents won't be found without this opt-in to the legacy format.
             entity.Property<string>("__id")
                   .ToJsonProperty("id")
                   .HasValueGeneratorFactory<LegacyIdGeneratorFactory>();
         });
     }
 }

 /// Reproduces EF Core 8's id format: "Product|{key}"
 class LegacyIdGenerator : ValueGenerator<string>
 {
     public override string Next(EntityEntry entry)
         => $"Product|{entry.Property("Id").CurrentValue}";
     public override bool GeneratesTemporaryValues => false;
 }

 class LegacyIdGeneratorFactory : ValueGeneratorFactory
 {
     public override ValueGenerator Create(
         Microsoft.EntityFrameworkCore.Metadata.IProperty property,
         Microsoft.EntityFrameworkCore.Metadata.ITypeBase typeBase)
         => new LegacyIdGenerator();
 }

 class Product { public int Id { get; set; } public string Sku { get; set; } }

